const fs = require('fs');
const path = require('path');

const TESTBED_DIR = '/workspace/testbed';
const sender = 'olivia';
const recipient = 'bob';
const subject = 'High Priority: Onboarding Equipment Setup Needed';
const content = \`Hello Bob,

I'm writing to request your assistance with a high-priority equipment setup for a newly onboarded contractor who is starting soon.

As outlined in the original onboarding request, the contractor requires the following before start of business on the next business day:

1. Standard Windows laptop — configured and ready for use
2. VPN access — fully provisioned and tested
3. Email account — set up and operational

Please prioritize this request to ensure the contractor has everything they need for a smooth first day.

Let me know if you have any questions or need additional information.

Best regards,
Olivia\`;

// Build the .eml content
const eml = [
  'From: ' + sender + '@example.com',
  'To: ' + recipient + '@example.com',
  'Subject: ' + subject,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=\"utf-8\"',
  '',
  content
].join('\r\n');

// Ensure directories exist
fs.mkdirSync(path.join(TESTBED_DIR, 'emails', sender), { recursive: true });
fs.mkdirSync(path.join(TESTBED_DIR, 'emails', recipient), { recursive: true });

// Save to both sender and recipient folders
for (const folder of [sender, recipient]) {
  const filePath = path.join(TESTBED_DIR, 'emails', folder, subject + '.eml');
  fs.writeFileSync(filePath, eml);
}

console.log('Successfully sent email to ' + recipient + '.');
"
